import{_ as a,o as n,a as l,b as p}from"./app.B47EjQll.js";const k=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"Utils API","link":"/api/Utils-API/Utils-API"},{"text":"SuperKernel","link":"/api/Utils-API/SuperKernel/SuperKernel"},{"text":"SkSystemArgs","link":"/api/Utils-API/SuperKernel/SkSystemArgs"}]},"headers":[],"relativePath":"api/Utils-API/SuperKernel/SkSystemArgs.md","filePath":"api/Utils-API/SuperKernel/SkSystemArgs.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"结构体定义","slug":"结构体定义","link":"#结构体定义"},{"level":2,"title":"成员说明","slug":"成员说明","link":"#成员说明"},{"level":2,"title":"成员函数说明","slug":"成员函数说明","link":"#成员函数说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"需要包含的头文件","slug":"需要包含的头文件","link":"#需要包含的头文件"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1793668861000}'),t={name:"api/Utils-API/SuperKernel/SkSystemArgs.md"};function c(e,s,d,i,r,o){return n(),l("div",null,[...s[0]||(s[0]=[p(`<div><article class="markdown-body"><h1>SkSystemArgs</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p><code>sk::SkSystemArgs</code>用于向SK子函数传递系统参数，包括子函数的block索引、block数量和early start同步配置。SK子函数需要使用这些系统参数或初始化系统变量时，可在入口参数中添加<code>sk::SkSystemArgs *sysArgs</code>，由SuperKernel框架传入；不需要时可以省略。完整适配规则请参见<a href="../../../guide/programming_guide/advanced_programming/super_kernel/kernel_direct_call_adaptation.html">核函数（Kernel）直调算子额外适配说明</a>。</p><h2 id="结构体定义">结构体定义<a class="header-anchor" href="#结构体定义">​</a></h2><p>该结构体由头文件提供，无需自行定义。以下展示主要成员：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">namespace</span><span class="w"> </span><span class="nn">sk</span><span class="w"> </span><span class="p">{</span>
<span class="k">struct</span><span class="w"> </span><span class="nc">SkSystemArgs</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">skBlockIdx</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">skNumBlocks</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">skTaskSyncCfg</span><span class="p">;</span>
<span class="w">    </span><span class="cm">/*其他预留信息*/</span>

<span class="w">    </span><span class="kr">inline</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">SkGetBlockIdx</span><span class="p">();</span>
<span class="w">    </span><span class="kr">inline</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">SkGetNumBlocks</span><span class="p">();</span>
<span class="w">    </span><span class="kr">inline</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">SkGetTaskSyncCfg</span><span class="p">();</span>
<span class="w">    </span><span class="kr">inline</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SkInit</span><span class="p">()</span><span class="w"> </span><span class="k">const</span><span class="p">;</span>
<span class="p">};</span>
<span class="p">}</span>
</code></pre></div><h2 id="成员说明">成员说明<a class="header-anchor" href="#成员说明">​</a></h2><table><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>skBlockIdx</td><td>uint16_t</td><td>SK子函数的block索引。</td></tr><tr><td>skNumBlocks</td><td>uint16_t</td><td>SK子函数的block数量。</td></tr><tr><td>skTaskSyncCfg</td><td>uint16_t</td><td>early start同步配置。</td></tr></tbody></table><h2 id="成员函数说明">成员函数说明<a class="header-anchor" href="#成员函数说明">​</a></h2><table><thead><tr><th>函数</th><th>返回值</th><th>说明</th></tr></thead><tbody><tr><td>SkGetBlockIdx()</td><td>uint16_t</td><td>返回<code>skBlockIdx</code>。</td></tr><tr><td>SkGetNumBlocks()</td><td>uint16_t</td><td>返回<code>skNumBlocks</code>。</td></tr><tr><td>SkGetTaskSyncCfg()</td><td>uint16_t</td><td>返回<code>skTaskSyncCfg</code>。</td></tr><tr><td>SkInit()</td><td>void</td><td>初始化SuperKernel场景下的系统变量。</td></tr></tbody></table><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>手写SK子函数适配Early-Start特性时，需添加<code>sk::SkSystemArgs *sysArgs</code>参数，并在调用<a href="../../SIMD-API/basic_api/sync_control/inter_task_sync/WaitPreTaskEnd.html">WaitPreTaskEnd</a>或<a href="../../SIMD-API/basic_api/sync_control/inter_task_sync/SetNextTaskStart.html">SetNextTaskStart</a>前调用<code>sysArgs-&gt;SkInit()</code>，显式初始化系统变量。</li><li>使用上述任务间同步接口时，还需在<a href="SK_BIND.html">SK_BIND</a>的<code>cap</code>参数中配置对应的Early-Start标记。</li><li>在SK场景下，原算子使用<code>AscendC::GetBlockNum()</code>时，可通过<code>sysArgs-&gt;skNumBlocks</code>或<code>sysArgs-&gt;SkGetNumBlocks()</code>获取SK子函数的block数量。</li><li>MIX 1:2场景中，vector核的<code>skNumBlocks</code>为原算子block num的2倍，使用时应注意与<code>AscendC::GetBlockNum()</code>的差异。</li></ul><h2 id="需要包含的头文件">需要包含的头文件<a class="header-anchor" href="#需要包含的头文件">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;kernel_operator.h&quot;</span>
</code></pre></div><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>以下代码展示如何在SK子函数中初始化系统变量并读取系统参数，<code>ArgsStruct</code>需按原核函数的参数定义，绑定方法参见<a href="SK_BIND.html">SK_BIND</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__sk__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">func_sk</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">ArgsStruct</span><span class="w"> </span><span class="o">*</span><span class="n">args</span><span class="p">,</span><span class="w"> </span><span class="n">sk</span><span class="o">::</span><span class="n">SkSystemArgs</span><span class="w"> </span><span class="o">*</span><span class="n">sysArgs</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">sysArgs</span><span class="o">-&gt;</span><span class="n">SkInit</span><span class="p">();</span>
<span class="w">    </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">blockIdx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">sysArgs</span><span class="o">-&gt;</span><span class="n">SkGetBlockIdx</span><span class="p">();</span>
<span class="w">    </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">blockNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">sysArgs</span><span class="o">-&gt;</span><span class="n">SkGetNumBlocks</span><span class="p">();</span>
<span class="w">    </span><span class="c1">// 使用args、blockIdx和blockNum完成算子计算。</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const u=a(t,[["render",c]]);export{k as __pageData,u as default};
